import type { BatchItem } from "drizzle-orm/batch";
import type { Database } from "./database.js";

/**
 * Runs the statements as ONE transaction: all of them or none. D1 has no interactive transactions (no
 * "read, decide, write inside one transaction"), only batches, so a multi-step write is built as a list
 * of statements known up front. Ids are generated by the app (not by the database) so a later statement
 * can refer to an earlier row; rules that depend on what is already stored (no overlapping reservation,
 * one active contract per property) are enforced by the database itself (trigger, partial unique index),
 * and reach the repository as a constraint error (see `errors.ts`).
 */
export async function atomic<const T extends readonly [BatchItem<"sqlite">, ...BatchItem<"sqlite">[]]>(
  db: Database,
  statements: T,
) {
  return db.batch(statements as unknown as readonly [BatchItem<"sqlite">, ...BatchItem<"sqlite">[]]);
}
